package io.github.miklires.mclans;import io.github.miklires.mclans.api.*;import io.github.miklires.mclans.storage.ClanRepository;import java.util.*;import java.util.concurrent.CompletableFuture;final class ClansApiService implements MClansApi{private final ClanRepository r;ClansApiService(ClanRepository r){this.r=r;}public CompletableFuture<Optional<ClanView>> clanOf(UUID p){return r.clanOf(p);}public CompletableFuture<List<ClanMemberView>> members(long id){return r.members(id);}public CompletableFuture<Boolean> areAllies(UUID a,UUID b){return r.clanOf(a).thenCombine(r.clanOf(b),(x,y)->{if(x.isEmpty()||y.isEmpty())return null;return new long[]{x.get().id(),y.get().id()};}).thenCompose(ids->ids==null?CompletableFuture.completedFuture(false):r.areAllies(ids[0],ids[1]));}}
